import logging
from abc import abstractmethod
from copy import deepcopy
import os

import importlib.util
import yaml

from .collector import ConfigurationFilesCollector
from .utils import config_vars_to_dict
from .rfs_utils import add_dicts
import re

current_dir = os.path.dirname(os.path.abspath(__file__))
tl = None


class ParameterProvider(object):

    @abstractmethod
    def load_params(self, yaml_data_file):
        pass


class YamlParameterProvider(ParameterProvider):

    def load_params(self, yaml_data_file):
        with open(yaml_data_file, 'r') as yaml_data:
            yaml_vars = yaml.load(yaml_data, Loader=yaml.Loader)
        if not yaml_vars:
            yaml_vars = {}
        return yaml_vars


class Config(object):

    def __init__(self, path, parameters_provider=YamlParameterProvider()):
        self.config_path = path
        if not os.path.exists(self.config_path):
            raise IOError('Config: {path} does not exist'.format(
                path=self.config_path))
        self.parameter_provider = parameters_provider
        self._config = self.parameter_provider.load_params(self.config_path)

    def __getattr__(self, attr):
        try:
            # self._config[attr] results in infinite recursion in Python3
            return self.__dict__['_config'][attr]
        except KeyError:
            raise AttributeError("{attr} does not exist".format(attr=attr))

    @property
    def config(self):
        return self._config


class ConfigsLoader(ConfigurationFilesCollector):

    def __init__(self, location, testline, parameter_provider=None):
        super(ConfigsLoader, self).__init__(location, testline)
        self.parameter_provider = parameter_provider or YamlParameterProvider()
        self._yaml_configs = []

    @property
    def config_files(self):
        """ Load all (testline and common) parameters from parsed yaml configuration files.
        Will fail with YAMLError for invalid yaml or with TypeError if yaml file is empty.
        Return list of Config objects"""
        if not self._yaml_configs:
            for yaml_data_file in self.get_all_yaml_configuration_files():
                self._yaml_configs.append(
                    Config(yaml_data_file, self.parameter_provider))
        return self._yaml_configs

    def get_config_parameters(self):
        """Returns dictionary with collected testline and common parameters"""
        parameters = [config.config for config in self.config_files]
        return {key: value for params in parameters for key, value in params.items()}


class TestlineParametersLoader(ConfigsLoader):

    def __init__(self, location, testline, env_config_id=1, parameter_provider=None):
        super(TestlineParametersLoader, self).__init__(
            location, testline, parameter_provider)
        self.env_config_path = os.path.join(
            self.testline_configs_path, "env_config_{}.yaml".format(env_config_id))
        self._env_config = None
        self._testline_parameters = None

    @property
    def env_config(self):
        if not self._env_config:
            for config in self.config_files:
                if config.config_path == self.env_config_path:
                    self._env_config = config
                    return self._env_config
            raise IOError("Env config {env_config} does not exists".format(
                env_config=self.env_config_path))
        return self._env_config

    @property
    def testline_parameters(self):
        if not self._testline_parameters:
            base_config = deepcopy(self.env_config)
            self._expand_testline_config_variables(base_config)
            self._testline_parameters = base_config
        return self._testline_parameters

    def _expand_testline_config_variables(self, base_config):
        testline_config_vars = config_vars_to_dict(
            base_config.TESTLINE_CONFIG_VARIABLES)
        testline_config_variables_tmp = deepcopy(testline_config_vars)
        config_parameters = self.get_config_parameters()
        for key, value in testline_config_vars.items():
            try:
                testline_config_variables_tmp[key] = config_parameters[value]
            except KeyError:
                logging.exception("TESTLINE_CONFIG_VARIABLES parameter {key}:{value} is not defined. Check your "
                                  "config files".format(key=key, value=value))
        base_config.config['TESTLINE_CONFIG_VARIABLES'] = testline_config_variables_tmp


class BaseTafConfigLoader(object):
    LEGACY_CONFIG_PATH = '/home/ute/robotlte/config/'
    GERRIT_CONFIG_PATH = '/home/ute/testline_configuration/'

    @abstractmethod
    def __init__(self, location=None, testline=None):
        self.location, self.testline = location, testline
        self.tl = self.import_init_file(self.location, self.testline)

    @abstractmethod
    def testline_parameters(self):
        pass

    def import_init_file(self, location=None, testline=None, config_var=None):
        if config_var:
            return config_var
        if location and testline:
            config_path = self._find_current_config_path(location, testline)
            init_file = os.path.join(config_path, "__init__.py")
            spec = importlib.util.spec_from_file_location("tl", init_file)
            if spec is None or spec.loader is None:
                raise ImportError(f"Cannot load module from {init_file}")
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            return module.tl
        raise ValueError("Either location and testline, or config_var must be provided")

    def _find_current_config_path(self, location, testline):
        gerrit_file_path = os.path.join(self.GERRIT_CONFIG_PATH, testline)
        if os.path.exists(gerrit_file_path):
            return gerrit_file_path
        return os.path.join(self.LEGACY_CONFIG_PATH, location, testline)

    @staticmethod
    def _get_rmods_interfaces_dict(rmod_list):
        rmod_interfaces_dict = {}
        for rmod in rmod_list:
            if rmod.pdu_port.pdu.model:
                pdu_type = rmod.pdu_port.pdu.model
            else:
                pdu_type = rmod.pdu_port.pdu.__class__.__name__
            rmod_interfaces_dict['RMOD_{}'.format(rmod.serial_number)] = {
                'IP': rmod.pdu_port.pdu.addr,
                'TYPE': pdu_type,
                'OUTLET': rmod.pdu_port.port_no,
                'CONTACTOR': rmod.pdu_port.contactor,
                'PDU_VERSION': rmod.pdu_port.pdu.version
            }
        return rmod_interfaces_dict

    @staticmethod
    def _get_smods_interfaces_dict(smod_list):
        smod_interfaces_dict = {}
        for smod in smod_list:
            if smod.pdu_port.pdu.model:
                pdu_type = smod.pdu_port.pdu.model
            else:
                pdu_type = smod.pdu_port.pdu.__class__.__name__
            smod_interfaces_dict['SMOD_{}'.format(smod.serial_number)] = {
                'IP': smod.pdu_port.pdu.addr,
                'TYPE': pdu_type,
                'OUTLET': smod.pdu_port.port_no,
                'CONTACTOR': smod.pdu_port.contactor,
                'PDU_VERSION': smod.pdu_port.pdu.version
            }
        return smod_interfaces_dict

    def _set_up_global_tl_var(self):
        global tl
        tl = self.tl


class TafConfigLoaderSBTS(BaseTafConfigLoader):

    def __init__(self, location, testline):
        super(TafConfigLoaderSBTS, self).__init__(location, testline)
        self.location, self.testline = location, testline
        self.tl = self.import_init_file(self.location, self.testline)
        self._set_up_global_tl_var()

    @property
    def testline_parameters(self):
        return add_dicts(self._build_interfaces_dict().items(), self._get_common_data_dicts().items())

    def _get_common_data_dicts(self):
        vars_list = ['PC_IP1', 'PC_IP2', 'MPLANE_IP',
                     'RNC', 'BSC', 'SMOD1', 'SMOD2']
        return self._get_testline_variables(vars_list)

    def _build_interfaces_dict(self):
        smod_interface_list = self._get_smods()
        smods = self._get_smods_interfaces_dict(smod_interface_list)
        rmod_interface_list = self._get_rmods()
        rmods = self._get_rmods_interfaces_dict(rmod_interface_list)

        intercaces_dict = {
            'INTERFACES': add_dicts(smods.items(), rmods.items())}
        return intercaces_dict

    def _get_testline_variables(self, var_list):
        testline_vars_dict = {}
        for var in var_list:
            try:
                testline_vars_dict[[var][0]] = self._get_param_values(var)
            except IndexError:
                continue
        return testline_vars_dict

    @staticmethod
    def _get_param_values(param):

        with open(os.path.join(current_dir, 'taf_adapter.yaml')) as fd:
            TAF_ADAPTER = yaml.safe_load(fd)
        taf_template_value = TAF_ADAPTER[param]

        param_dict = {}
        if isinstance(taf_template_value, dict):
            for var, val in taf_template_value.items():
                try:
                    param_dict[var] = eval(val)
                except SyntaxError:
                    param_dict[var] = val
                except TypeError:
                    # Missing var to assign val - eg. GSM not configured, so tl.bscs[0] missing in config
                    continue
            return param_dict
        else:
            return eval(taf_template_value)

    def _get_rmods(self):
        num_of_enbs = len(self.tl.enbs)
        rmod_list = []
        for enb in range(num_of_enbs):
            rmod_list.extend(self.tl.enbs[enb].rms)
        return rmod_list

    def _get_smods(self):
        num_of_enbs = len(self.tl.enbs)
        smod_list = []
        for enb in range(num_of_enbs):
            if self.tl.enbs[enb].system_module.common_units:
                smod_list.extend(self.tl.enbs[enb].system_module.common_units)
            else:
                smod_list.extend(self.tl.enbs[enb].system_module.core_units)
        return smod_list


class TafConfigLoaderRFS(BaseTafConfigLoader):

    def __init__(self, location=None, testline=None, config_var=None):
        super(TafConfigLoaderRFS, self).__init__(location, testline)
        self.location, self.testline, self.config_var = location, testline, config_var
        self.tl = self.import_init_file(self.location, self.testline, self.config_var)
        self._set_up_global_tl_var()

    @property
    def testline_parameters(self):
        variables_dict = add_dicts(self._get_common_entity_data_dicts().items(),
                                   self.import_additional_variables().items(),
                                   self._get_common_general_data_dicts().items(),
                                   self._get_common_entity_interface_data_dicts().items())
        final_dict = add_dicts(variables_dict.items(),
                               self._get_alias_info(variables_dict).items())
        return final_dict

    def _get_alias_info(self, var_dict):

        output_dict = {}

        all_keys = list(var_dict.keys())
        alias_list = []
        alias_list_complete = []
        for key in all_keys:
            matches = re.findall(r'(MASTER|SLAVE\d*)', key)
            alias_list.extend([match.title() for match in matches])
            matches = re.findall(r'MASTER(?:_EXT)?|SLAVE\d*(?:_EXT)?', key)
            alias_list_complete.extend([match.title() for match in matches])

        output_dict['alias_list'] = sorted(set(alias_list))
        output_dict['alias_list_complete'] = sorted(set(alias_list_complete))
        output_dict['alias_list_count'] = len(output_dict['alias_list'])
        output_dict['alias_list_complete_count'] = len(
            output_dict['alias_list_complete'])

        return output_dict

    def _get_common_entity_data_dicts(self):
        vars_list = ['ENTITY', 'ENTITY_EXT']
        entity_name_list = self._generate_entity_name_list(
            len(eval("tl.test_pcs")))
        returned_entities = {}
        idx = 0
        for entry in eval("tl.test_pcs"):
            current_tech = self.determine_current_entity_tech(entry, idx)

            if current_tech is None:
                continue

            if current_tech[1] == 'CBTS':
                testline_vars = self._get_testline_variables(
                    ['CLOUD_ENTITY'], current_tech)
                updated_vars = self._update_cbts_entity(
                    testline_vars, current_tech)
            else:
                testline_vars = self._get_testline_variables(
                    vars_list, current_tech)
                updated_vars = self._update_specific_rfs_vars(
                    testline_vars, current_tech)

            returned_entities = add_dicts(returned_entities,
                                          self._set_correct_entity_name(updated_vars, entity_name_list[idx]))

            idx = idx + 1

        return returned_entities

    def _update_cbts_entity(self, var_dict, current_tech):
        var_dict = self._update_vdu_entity(var_dict, current_tech)

        return var_dict

    def _get_common_general_data_dicts(self):
        vars_list = ['BTS_USERNAME', 'BTS_PASSWORD',
                     'BSC_telnet', 'BSC_ssh', 'OPTICAL_SWITCH', 'RNC', 'NETACT']
        general_vars = self._get_testline_variables(vars_list)
        general_updated_vars = self._update_variables_dict_with_correct_bsc_entity(
            general_vars)
        return general_updated_vars

    def _get_common_entity_interface_data_dicts(self):

        vars_list = ['ENTITY_INTERFACE', 'ENTITY_EXT_INTERFACE']
        smod_interface_dict_list = []
        entity_name_list = self._generate_entity_name_list(
            len(eval("tl.test_pcs")))
        idx = 0
        for entry in eval("tl.test_pcs"):
            current_tech = self.determine_current_entity_tech(entry, idx)
            logging.debug("Current TECH: {}".format(current_tech))
            if current_tech is None:
                continue

            if current_tech[1] == 'CBTS':
                pass
            else:
                created_dicts = self._get_testline_variables(
                    vars_list, current_tech)
                smod_interface_dict_list.append(self._set_correct_interfaces_entity_name
                                                (created_dicts, entity_name_list[idx]))

            idx = idx + 1

        smods = self._get_smods_interfaces_dict(smod_interface_dict_list)
        smods_anchor = self._set_anchors(smod_interface_dict_list)

        rmod_interface_list = self._get_rmods()
        rmods = self._get_rmods_interfaces_dict(rmod_interface_list)

        fhs_interface_list = self._get_fhs()
        fhs = self._get_fhs_dict(fhs_interface_list)

        fhgw_interface_list = self._get_fhgw()
        fhgw = self._get_fhgw_dict(fhgw_interface_list)

        bbmod_interface_list = self._get_bbmods()
        bbmods = self._get_bbmods_interfaces_dict(bbmod_interface_list)

        interfaces_dict = {
            'INTERFACES': add_dicts(smods.items(), rmods.items(), bbmods.items(), smods_anchor.items(), fhs.items(),
                                    fhgw.items())}
        logging.debug("Interfaces: {}".format(interfaces_dict))
        return interfaces_dict

    def _get_testline_variables(self, var_list, current_tech=None):
        testline_vars_dict = {}
        for var in var_list:
            try:
                testline_vars_dict[[var][0]] = self._get_param_values(
                    var, current_tech)
            except IndexError:
                continue
        return testline_vars_dict

    def _get_param_values(self, param, current_tech=None):

        with open(os.path.join(current_dir, 'taf_rfs_adapter.yaml')) as fd:
            TAF_RFS_ADAPTER = yaml.safe_load(fd)
        taf_template_value = TAF_RFS_ADAPTER[param]

        param_dict = {}
        logging.debug(
            "Processing for: {} - {} - {}".format(current_tech, param, taf_template_value))
        if isinstance(taf_template_value, dict):
            return self.process_template_values(taf_template_value, param, current_tech, param_dict)
        else:
            return taf_template_value

    def process_evaluation(self, var, val, param, current_tech):
        value = ""
        if 'OAM' in var or var == 'BCF_ID':
            value = self._determine_type_for_specific_parameters(
                var, param, current_tech) + val
        else:
            value = self._determine_type(param, var, current_tech) + val
        evaluation = eval(value)
        return evaluation

    def process_template_values(self, taf_template_value, param, current_tech, param_dict):
        for var, val in taf_template_value.items():
            try:
                evaluation = self.process_evaluation(
                    var, val, param, current_tech)
                if (evaluation == "None") or (evaluation is None):
                    logging.debug(
                        "Not Stored {} - {} - {} - {} -> {}".format(current_tech, param, var, val, evaluation))
                    continue
                param_dict[var] = evaluation
                logging.debug(
                    "Stored {} - {} - {} - {} -> {}".format(current_tech, param, var, val, evaluation))
            except (SyntaxError, NameError) as m:
                logging.debug(
                    "Stored - Exception triggered - {} - {} - {} - {} - {} -> {}".format(m, current_tech, param, var,
                                                                                         val, val))
                param_dict[var] = val
            except (TypeError, AttributeError):
                logging.debug(
                    "Not Stored - Exception triggered - {} - {} - {} - {} -> None".format(current_tech, param, var,
                                                                                          val))
                # Missing var to assign val - eg. GSM not configured, so tl.bscs[0] missing in config
                continue
        return param_dict

    def _get_rmods(self):
        rmod_list = []
        for tech in self._get_rfs_available_tl_obj_types():
            num = len(eval(tech))
            for bts in range(num):
                if tech in 'tl.gnbs':
                    rmod_list.extend(self._get_gnb_rmods(tech, bts))
                else:
                    rmod_list.extend(eval(tech)[bts].rms)
                    rmod_list.extend(self._get_total_rmods(
                        eval(tech)[bts].system_module))
        return rmod_list

    def _get_fhs(self):
        fhs_list = []
        for tech in self._get_rfs_available_tl_obj_types():
            num = len(eval(tech))
            for bts in range(num):
                try:
                    if tech in 'tl.gnbs':
                        fhs_list.extend(self._get_fhs_from_units(
                            eval(tech)[bts].dus[0].airscale.common_units))
                    else:
                        fhs_list.extend(self._get_fhs_from_units(
                            eval(tech)[bts].system_module.common_units))
                except Exception:
                    pass
        return fhs_list

    def _get_fhgw(self):
        fhgw_list = []
        for tech in self._get_rfs_available_tl_obj_types():
            num = len(eval(tech))
            for bts in range(num):
                try:
                    if tech in 'tl.gnbs':
                        fhgw_list.extend(
                            self._get_fhgw_from_units(eval(tech)[bts].dus))
                except Exception:
                    pass
        return fhgw_list

    @staticmethod
    def _get_fhs_from_units(unit):
        fhs_list = []
        try:
            for commonunit in unit:
                for capacityunit in commonunit.capacity_units:
                    fhs_list.extend(capacityunit.fhs)
        except AttributeError:
            pass

        return fhs_list

    @staticmethod
    def _get_fhgw_from_units(unit):
        fhgw_list = []
        try:
            for vdu in unit:
                if vdu.fhgws is not None:
                    fhgw_list.extend(vdu.fhgws)
        except AttributeError:
            pass

        return fhgw_list

    def _get_gnb_rmods(self, tech, bts):
        rmod_list = []
        for du in eval(tech)[bts].dus:
            rmod_list.extend(self._get_du_rmods(du))
            rmod_list.extend(self._get_total_rmods(du))
            rmod_list.extend(self._get_fhgw_rmods(du))
            rmod_list.extend(self._get_rannic_rmods(du))
        return rmod_list

    @staticmethod  # noqa: C901
    def _get_total_rmods(dist_unit):  # noqa: C901
        rmod_list = []
        try:
            system_module = dist_unit.airscale
        except AttributeError:
            return rmod_list
        if system_module.common_units is not None:
            for common_unit in system_module.common_units:
                if common_unit.rus is not None:
                    rmod_list.extend(common_unit.rus)
                try:
                    for capacity_unit in common_unit.capacity_units:
                        if capacity_unit.rus is not None:
                            rmod_list.extend(capacity_unit.rus)
                except (AttributeError, TypeError):
                    continue
        try:
            if system_module.core_units is not None:
                for core_unit in system_module.core_units:
                    if core_unit.rus is not None:
                        rmod_list.extend(core_unit.rus)
        except AttributeError:
            return rmod_list

        return rmod_list

    @staticmethod
    def _get_du_rmods(du):
        rmod_list = []
        try:
            if du.rus is not None:
                rmod_list.extend(du.rus)
        except AttributeError:
            pass

        return rmod_list

    @staticmethod
    def _get_fhgw_rmods(du):
        rmod_list = []
        try:
            if du.fhgws is not None:
                for fhgw in du.fhgws:
                    if fhgw.rus is not None:
                        rmod_list.extend(fhgw.rus)
        except AttributeError:
            pass
        return rmod_list

    @staticmethod
    def _get_rannic_rmods(du):
        rmod_list = []
        try:
            if du.rannics is not None:
                for rannic in du.rannics:
                    if rannic.rus is not None:
                        rmod_list.extend(rannic.rus)
        except AttributeError:
            pass
        return rmod_list

    def _get_bbmods(self):
        bbmod_list = []
        for tech in self._get_rfs_available_tl_obj_types():
            num = len(eval(tech))
            for bts in range(num):
                try:
                    if tech in 'tl.gnbs':
                        bbmod_list.extend(
                            eval(tech)[bts].dus[0].airscale.common_units[0].capacity_units)
                    else:
                        bbmod_list.extend(
                            eval(tech)[bts].system_module.common_units[0].capacity_units)
                except (TypeError, AttributeError):
                    continue
        return bbmod_list

    def _determine_type(self, param, var=None, current_tech=None):  # noqa: C901

        prepend_list = ['MODULE_TYPE', 'TECH_IP_ADDRESS', 'CONTACTOR', 'VERSION', 'IM_IP_ADDRESS', 'PduPort',
                        'SERIAL_NUM', 'IP', 'TYPE', 'OUTLET', 'UDP_IP_ADDRESS', 'PC_IP_ADDRESS', 'PC_SSH_USERNAME',
                        'PC_SSH_PASSWORD', 'PC_SSH_PORT', 'EXT_MODULE_TYPE', 'EXT_TECH_IP_ADDRESS', 'EXT_IM_IP_ADDRESS',
                        'EXT_UDP_IP_ADDRESS', 'EXT_PC_IP_ADDRESS', 'EXT_UDP_IP_ADDRESS', 'EXT_PC_IP_ADDRESS',
                        'EXT_PC_SSH_PORT', 'EXT_PC_SSH_USERNAME', 'EXT_PC_SSH_PASSWORD']

        val = ''
        try:
            if current_tech[1] == 'CBTS':
                prepend_list = ['CU_IP_ADDRESS',
                                'CU_USERNAME', 'CU_PASSWORD', 'CU_PORT']
        except Exception:
            pass

        direct_list = ['DCAP_IP_ADDRESS', 'DCAP_PORT',
                       'DCAP_USERNAME', 'DCAP_PASSWORD']
        if var in prepend_list:
            if param in ['ENTITY', 'ENTITY_INTERFACE', 'ENTITY_EXT', 'ENTITY_EXT_INTERFACE', 'CLOUD_ENTITY']:
                val = self.create_var_path(current_tech)

        if param in prepend_list:
            val = self.create_var_path(current_tech)

        if var in direct_list:
            val = current_tech[0] + '.'

        return val

    def create_var_path(self, current_tech):
        if current_tech[1] == 'CBTS':
            return current_tech[0] + "."
        if current_tech[1] == 'NR':
            return self.determine_current_unit_name(current_tech[0] + '.' + 'dus[0].airscale' + '.')
        else:
            return self.determine_current_unit_name(current_tech[0] + '.' + 'system_module' + '.')

    def determine_current_unit_name(self, obj_name):
        if eval(obj_name + "common_units"):
            return obj_name + "common_units"

        if eval(obj_name + "core_units"):
            return obj_name + "core_units"

    @staticmethod
    def _determine_type_for_specific_parameters(var=None, parent_var=None, current_tech=None):

        prepend_list = ['OAM_IP_ADDRESS', 'BCF_ID']
        mapping_dict = {
            'ENTITY': {'SRAN': current_tech[0] + '.' + 'oam_ip' + '.',
                       'NR': current_tech[0] + '.' + 'cu.backhaul_site_oam_ip' + '.'
                       },
        }

        val = ''

        if var in prepend_list:
            try:
                if var == 'BCF_ID' and parent_var == 'ENTITY':
                    val = current_tech[0] + '.'
                elif 'ENTITY' in parent_var:
                    val = mapping_dict['ENTITY'][current_tech[1]]
            except KeyError:
                return val
        return val

    @staticmethod
    def _get_rfs_available_tl_obj_types():
        tl_objects = ["tl.gnbs", "tl.enbs",
                      "tl.nb_objects", "tl.bts2g_objects"]
        return [tl_obj for tl_obj in tl_objects if eval(tl_obj) is not None]

    def _get_rfs_avaiable_tl_obj_names(self):
        obj_names = []
        objects = self._get_rfs_available_tl_obj_types()
        for entry in objects:
            for idx in range(len(eval(entry))):
                obj_names.append("{}[{}]".format(entry, idx))
        return obj_names

    def _update_specific_rfs_vars(self, var_dict, current_tech=None):

        var_dict = self.update_airscale_type(var_dict)
        var_dict = self.update_current_tech(var_dict, current_tech)
        var_dict = self.update_ext_module(var_dict)

        return var_dict

    def _update_vdu_entity(self, var_dict, current_tech):
        vdu_list = eval(current_tech[0]).dus
        var_dict['CLOUD_ENTITY']['VDU'] = self._get_vdu_dict(vdu_list)
        return var_dict

    def update_airscale_type(self, var_dict):
        try:
            if var_dict["ENTITY"]["MODULE_TYPE"] in ["ASIA", "ASIB", "ASIK", "ASIL", "ASIM"]:
                var_dict["ENTITY"]["MODULE_TYPE"] = "ASIA"
        except Exception:
            pass

        return var_dict

    def update_current_tech(self, var_dict, current_tech):
        try:
            var_dict["ENTITY"]["TECH"] = current_tech[1]
        except Exception:
            pass

        return var_dict

    def update_ext_module(self, var_dict):
        try:
            if var_dict["ENTITY_EXT"]:
                var_dict["ENTITY_EXT"]["EXT_MODULE_TYPE"] = var_dict["ENTITY"]["MODULE_TYPE"]
        except Exception:
            pass

        return var_dict

    def _update_variables_dict_with_correct_bsc_entity(self, var_dict):
        try:
            key_to_replace = "BSC_ssh" if var_dict["BSC_ssh"].get(
                "ip", None) else "BSC_telnet"
            var_dict["BSC"] = var_dict.pop(key_to_replace)
            var_dict["BSC_CONNECTION_TYPE"] = key_to_replace.split('_')[1]
            var_dict.pop(key_to_replace)
        except Exception:
            pass

        return var_dict

    @staticmethod
    def _set_anchors(smod_dict_list):
        smod_interfaces_dict = {}
        anchor_fsm = ''
        for entry in smod_dict_list:
            for smod_key in entry.keys():
                try:
                    anchor_fsm = smod_key.replace("_INTERFACE", "_fsm").lower()
                except Exception:
                    continue

                smod_interfaces_dict[anchor_fsm] = entry[smod_key]
        return smod_interfaces_dict

    def import_additional_variables(self):

        additional_vars_dict = {}
        config_path = self._find_current_config_path(
            self.location, self.testline)
        init_file = os.path.join(config_path, "__init__.py")
        spec = importlib.util.spec_from_file_location("fullpackage", init_file)
        if spec is None or spec.loader is None:
            raise ImportError(f"Cannot load module from {init_file}")
        var_pack = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(var_pack)
        logging.info(var_pack)

        for additional_vars in ['UTE_UE_CONFIG', 'UEM_CONFIG_PATH', 'ATTENUATOR_CONFIG_PATH',
                                'TARGET_LOGICAL_CONFIG_PATH', 'RFS_TL_FLAGS', 'OPTICAL_SWITCH_CONFIG',
                                'DCAP_PROFILES_CONFIG_PATH', 'RSI_CONFIG_PATH', 'CELL_TARGET_BW_PATH']:
            try:
                evaluation = eval("var_pack." + additional_vars)
                logging.debug(
                    "Stored - {} -> {}".format(additional_vars, evaluation))
            except (TypeError, AttributeError):
                logging.debug(
                    "Not Stored - {} -> None".format(additional_vars))
                continue
            else:
                additional_vars_dict[additional_vars] = evaluation

        return additional_vars_dict

    @staticmethod
    def _get_bbmods_interfaces_dict(bbmod_list):
        bbmods_interfaces_dict = {}
        for bbmod in bbmod_list:
            try:
                bbmods_interfaces_dict['BBMOD_{}'.format(bbmod.serial_number)] = {
                    'IP': bbmod.pdu_port.pdu.addr,
                    'TYPE': bbmod.pdu_port.pdu.model if bbmod.pdu_port.pdu.model else bbmod.pdu_port.pdu.__class__.__name__,
                    'OUTLET': bbmod.pdu_port.port_no,
                    'CONTACTOR': bbmod.pdu_port.contactor,
                    'VERSION': bbmod.pdu_port.pdu.version,
                    'PduPort': bbmod.pdu_port
                }
            except (TypeError, AttributeError):
                pass
        return bbmods_interfaces_dict

    def _get_vdu_dict(self, vdu_list):
        created_vdu_list = []
        for vdu in vdu_list:
            try:
                vdu_dict = {
                    'IP_ADDRESS': vdu.oam_http_connection_details.addr,
                    'USERNAME': vdu.oam_http_connection_details.username,
                    'PASSWORD': vdu.oam_http_connection_details.password,
                    'PORT': vdu.oam_http_connection_details.port
                }
                created_vdu_list.append(vdu_dict)
            except (TypeError, AttributeError):
                pass
        return created_vdu_list

    def determine_current_entity_tech(self, current_object, idx=None):  # noqa: C901
        objects_list = self._get_rfs_avaiable_tl_obj_names()
        for tech_obj in objects_list:
            if self.determine_current_entity_tech_name(tech_obj) == "NR":
                evaluation = self.determine_current_unit_name(
                    "{}.dus[0].airscale.".format(tech_obj))
                if current_object == eval(evaluation)[0].test_pc:
                    tech_name = self.determine_current_entity_tech_name(
                        tech_obj)
                    return tech_obj, tech_name
            if self.determine_current_entity_tech_name(tech_obj) == "CBTS":
                if idx == 0:
                    tech_name = self.determine_current_entity_tech_name(
                        tech_obj)
                    return tech_obj, tech_name
            if self.determine_current_entity_tech_name(tech_obj) == "SRAN":
                evaluation = self.determine_current_unit_name(
                    "{}.system_module.".format(tech_obj))
                if current_object == eval(evaluation)[0].test_pc:
                    tech_name = self.determine_current_entity_tech_name(
                        tech_obj)
                    return tech_obj, tech_name

    def determine_current_entity_tech_name(self, tech_obj):
        if eval(tech_obj).__class__.__name__ in ["RealEnb"]:
            return "SRAN"
        elif eval(tech_obj).__class__.__name__ in ["gNB", "ClassicalBts"]:
            return "NR"
        elif eval(tech_obj).__class__.__name__ in ["CloudBts"]:
            return "CBTS"
        else:
            return None

    @staticmethod
    def _get_rmods_interfaces_dict(rmod_list):
        rmod_interfaces_dict = {}
        for rmod in rmod_list:
            radio_type = re.search(r"RadioTypes.([A-Za-z0-9]+).value", str(rmod.radio_type))
            rmod_interfaces_dict['RMOD_{}'.format(rmod.serial_number)] = {
                'RADIO_TYPE': radio_type.group(1) if radio_type else rmod.radio_type,
                'RADIO_SSH_USERNAME': rmod.default_ssh_connection_details.username if rmod.default_ssh_connection_details else None,
                'RADIO_SSH_PASSWORD': rmod.default_ssh_connection_details.password if rmod.default_ssh_connection_details else None,
                'RADIO_SSH_IP_ADDR': rmod.default_ssh_connection_details.addr if rmod.default_ssh_connection_details else None,
                'IP': rmod.pdu_port.pdu.addr,
                'TYPE': rmod.pdu_port.pdu.model if rmod.pdu_port.pdu.model else rmod.pdu_port.pdu.__class__.__name__,
                'OUTLET': rmod.pdu_port.port_no,
                'CONTACTOR': rmod.pdu_port.contactor,
                'VERSION': rmod.pdu_port.pdu.version,
                'PduPort': rmod.pdu_port,
                'lmi': rmod if getattr(rmod, 'lmi', None) else None
            }
        return rmod_interfaces_dict

    @staticmethod
    def _get_fhs_dict(fhs_list):
        fhs_dict = {}
        for fhs in fhs_list:
            fhs_dict['FHS_{}'.format(fhs.serial_number)] = {
                'FHS_TYPE': fhs.fhs_type,
                'IP': fhs.pdu_port.pdu.addr,
                'TYPE': fhs.pdu_port.pdu.model,
                'OUTLET': fhs.pdu_port.port_no,
                'CONTACTOR': fhs.pdu_port.contactor,
                'VERSION': fhs.pdu_port.pdu.version,
                'PduPort': fhs.pdu_port,
            }
        return fhs_dict

    @staticmethod
    def _get_fhgw_dict(fhgw_list):
        fhgw_dict = {}
        for fhgw in fhgw_list:
            fhgw_dict['FHGW_{}'.format(fhgw.fhgw_id)] = {
                'IP': getattr(fhgw.default_ssh_connection_details, 'addr', None),
                'USERNAME': getattr(fhgw.default_ssh_connection_details, 'username', None),
                'PASSWORD': getattr(fhgw.default_ssh_connection_details, 'password', None),
                'PORT': getattr(fhgw.default_ssh_connection_details, 'port', None),
                'CONNECTIONS': ['RMOD_{}'.format(ru.serial_number) for ru in fhgw.rus] if hasattr(fhgw, 'rus') and fhgw.rus is not None else [],
            }
        return fhgw_dict

    @staticmethod
    def _get_smods_interfaces_dict(smod_interface_list):
        smod_interfaces_dict = {}
        for entity in smod_interface_list:
            for smod in entity.values():
                if smod == {}:
                    break
                new_key = 'SMOD_{}'.format(smod['SERIAL_NUM'])
                del smod['SERIAL_NUM']
                smod_interfaces_dict[new_key] = smod
        return smod_interfaces_dict

    @staticmethod
    def _generate_entity_name_list(count):

        if count == 1:
            return ["MASTER"]
        elif count == 2:
            return ["MASTER", "SLAVE"]
        else:
            return ["MASTER", "SLAVE"] + ["SLAVE{}".format(idx) for idx in range(1, count - 1)]

    @staticmethod  # noqa: C901
    def _set_correct_entity_name(entities_dict, entity_name):  # noqa: C901
        final_dict = {}
        for subdict in entities_dict.keys():
            updated_dict = {}
            if isinstance(entities_dict[subdict], list):
                updated_dict[subdict] = entities_dict[subdict]
                continue
            for key in entities_dict[subdict].keys():
                if key == "OAM_IP_ADDRESS" and (entities_dict[subdict][key] == "v4"):
                    continue
                if key == "BCF_ID":
                    updated_dict[key] = entities_dict[subdict][key]
                else:
                    updated_dict[entity_name + "_" +
                                 key] = entities_dict[subdict][key]
            if subdict == 'CLOUD_ENTITY':
                final_dict[subdict.replace(
                    "CLOUD_ENTITY", entity_name)] = updated_dict
            else:
                final_dict[subdict.replace(
                    "ENTITY", entity_name)] = updated_dict

        return final_dict

    @staticmethod
    def _set_correct_interfaces_entity_name(entities_dict, entity_name):
        final_dict = {}
        for subdict in entities_dict.keys():
            final_dict[subdict.replace(
                "ENTITY", entity_name)] = entities_dict[subdict]
        return final_dict
